gNA(){return"\u09aa\u09cb\u09b8\u09cd\u099f \u0995\u09b0\u09be \u099a\u09be\u09b2\u09be\u09a8, \u0995\u09cd\u09b0\u09af\u09bc, \u098f\u09ac\u0982 \u09ad\u09be\u0989\u099a\u09be\u09b0 \u09b8\u09ae\u09cd\u09aa\u09be\u09a6\u09a8\u09be \u098f\u09ac\u0982 \u09ae\u09c1\u099b\u09c7 \u09ab\u09c7\u09b2\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7 \u2014 \u09b8\u09be\u09a7\u09be\u09b0\u09a3\u09a4 \u09b6\u09c1\u09a7\u09c1\u09ae\u09be\u09a4\u09cd\u09b0 \u09ae\u09be\u09b2\u09bf\u0995\u09c7\u09b0 \u099c\u09a8\u09cd\u09af\u0964"},
gNF(){return"\u099f\u09bf\u09ae \u09b8\u09a6\u09b8\u09cd\u09af \u09b8\u09ae\u09cd\u09aa\u09be\u09a6\u09a8\u09be \u0995\u09b0\u09c1\u09a8"},
gNL(){return"\u09ab\u09cb\u09a8 (\u0990\u099a\u09cd\u099b\u09bf\u0995)"},
