gT8(){return"\u091c\u0948\u0938\u0947 AFT \u2192 AFT-001, AFT-002 \u2026 \u0915\u0947\u0935\u0932 \u0928\u090f \u091a\u093e\u0932\u093e\u0928\u094b\u0902 \u0915\u094b \u092a\u094d\u0930\u092d\u093e\u0935\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948\u0964"},
gSK(){return"\u0916\u093e\u0924\u093e \u0936\u0940\u0930\u094d\u0937\u0915"},
